    [4122]={name="Bookmaker's Scepter",quality=2,ilvl=37,sourceType="quest_reward",instructions="Reward from the quest 'The Hidden Key'. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="The Hidden Key",lore="Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key."},
    [4123]={name="Frost Metal Pauldrons",quality=2,ilvl=37,sourceType="quest_reward",instructions="Reward from the quest 'Report to Doren' - pick it over the other choices. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Report to Doren",lore="Did Lieutenant Doren want you to report back to him with that patrol information?"},
    [4129]={name="Collection Plate",quality=2,ilvl=44,sourceType="quest_reward",instructions="Reward from the quest 'Cracking Maury's Foot'. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Cracking Maury's Foot",lore="Curses! That swab Maury put a lock on his foot, and I can't open it! His loot's inside the foot, and that's what he owes me! We need to find the key to open the lock."},
    [4130]={name="Smotts' Compass",quality=2,ilvl=50,sourceType="quest_reward",instructions="Reward from the quest 'Facing Negolash'. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Facing Negolash",lore="Negolash is a hungry giant. When the giants destroyed our ship, Negolash went straight for my kitchen. He wasn't hungry for crew like the other giants."},
    [4132]={name="Darkspear Armsplints",quality=2,ilvl=37,sourceType="quest_reward",instructions="Reward from the quest 'Headhunting' - pick it over the other choices. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Headhunting",lore="We must find if Yenniku is dead. Slay the Bloodscalp Headhunters and take from them their Shrunken Heads. You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them."},
