    [5275]={name="Binding Girdle",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'The Disruption Ends' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Disruption Ends",lore="One of my scouts witnessed an attack on a caravan from Durotar. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout."},
    [5310]={name="Sea Dog Britches",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'The Guns of Northwatch' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Guns of Northwatch",lore="Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold! Those bastards must be dealt with. Their paranoia has them in a state of frenzy."},
    [5319]={name="Bashing Pauldrons",quality=1,ilvl=20,reqLevel=15,sourceType="world_drop",instructions="Drops from Haren Swifthoof (rare elite) in The Loch.",zone="The Loch",npc="Haren Swifthoof"},
    [5320]={name="Padded Lamellar Boots",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'Stolen Booty' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Stolen Booty",lore="While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have! As you see, my observatory is ready to go, but it needs the smaller of the two lenses."},
    [5321]={name="Elegant Shortsword",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Serena Bloodfeather' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Serena Bloodfeather",lore="You did so well with the lieutenants and underlings that I'd like you to do one last thing for me. Serena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago."},
    [5324]={name="Engineer's Hammer",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'Samophlange' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Samophlange",lore="Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose."},
    [5325]={name="Welding Shield",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'Samophlange' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Samophlange",lore="Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose."},
    [5328]={name="Cinched Belt",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'The Disruption Ends' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Disruption Ends",lore="One of my scouts witnessed an attack on a caravan from Durotar. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout."},
    [5345]={name="Stonewood Hammer",quality=2,ilvl=14,sourceType="quest_reward",instructions="Reward from the quest 'Centaur Bracers' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Centaur Bracers",lore="The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops. And so, I have a bounty task for you."},
    [5351]={name="Bounty Hunter's Ring",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Hezrul Bloodmark'. In The Barrens.",zone="The Barrens",questName="Hezrul Bloodmark",lore="Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us."},
    [5395]={name="Woodland Shield",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Webwood Egg' - pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="Webwood Egg",lore="Now that I have the spiders' venom, I'd like some live specimens to study. Unfortunately, capturing a living, giant spider is more than I can ask of you, young."},
    [5399]={name="Tracking Boots",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Woodland Protector' - pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="The Woodland Protector",lore="Something evil is brewing in the forests of Teldrassil. Look long the hills to where the peaceful furbolgs used to dwell. They have deserted their homes and are amassing under the name of the Gnarlpine tribe."},
    [5404]={name="Serpent's Shoulders",quality=3,ilvl=23,reqLevel=18,sourceType="boss_drop",instructions="Drops from Lady Anacondra in Wailing Caverns.",zone="Wailing Caverns",npc="Lady Anacondra"},
