    [6063]={name="Cold Steel Gauntlets",quality=1,ilvl=8,sourceType="quest_reward",instructions="Reward from the quest 'Graverobbers' - pick it over the other choices. In Tirisfal Glades.",zone="Tirisfal Glades",questName="Graverobbers",lore="The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came."},
    [6084]={name="Stormwind Guard Leggings",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Wanted:  \"Hogger\"' - pick it over the other choices. In Elwynn Forest.",zone="Elwynn Forest",questName="Wanted:  \"Hogger\"",lore="He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."},
    [6087]={name="Chausses of Westfall",quality=3,ilvl=24,sourceType="quest_reward",instructions="Reward from the quest 'The Defias Brotherhood' - pick it over the other choices. In The Deadmines.",zone="The Deadmines",questName="The Defias Brotherhood",lore="Edwin VanCleef must be assassinated. While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all."},
