    [6665]={name="Hexed Bracers",quality=2,ilvl=26,sourceType="quest_reward",instructions="Reward from the quest 'Jin'Zil's Forest Magic' - pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="Jin'Zil's Forest Magic",lore="So excited I am! Three little cages for three little elves! But what shall we do with our lovely tree-hugging friends? Why, let's give them a taste of..."},
    [6671]={name="Juggernaut Leggings",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'The Den'. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="The Den",lore="The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items. They devised a complex scheme to keep them from falling into the wrong hands."},
    [6676]={name="Constable Buckler",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Reclaiming the Charred Vale' - pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="Reclaiming the Charred Vale",lore="The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken. Far south of the Barrens lies a land known as Thousand Needles."},
    [6678]={name="Band of Elven Grace",quality=2,ilvl=28,sourceType="quest_reward",instructions="Reward from the quest 'Reception from Tyrande'. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="Reception from Tyrande",lore="I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission. It may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains."},
