    [6722]={name="Beastial Manacles",quality=2,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Fallen Sky Lake' - pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Fallen Sky Lake",lore="Relara's fever has passed, but she is still very weak. I do not believe time alone will give her back the strength she has lost. I believe it will take the power of a moonstone."},
    [6723]={name="Medal of Courage",quality=3,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'Saving Yenniku' - pick it over the other choices. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Saving Yenniku",lore="I have reshaped the Mind's Eye into a Soul Gem. Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul."},
    [6725]={name="Marbled Buckler",quality=3,ilvl=36,sourceType="quest_reward",instructions="Reward from the quest 'The Crone of the Kraul' - pick it over the other choices. In Razorfen Kraul.",zone="Razorfen Kraul",questName="The Crone of the Kraul",lore="Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was. We must not let their valiance go for naught. This crone... Charlga Razorflank..."},
    [6730]={name="Ironforge Chain",quality=2,ilvl=16,reqLevel=11,sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
    [6747]={name="Enforcer Pauldrons",quality=2,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'The Corrupter' - pick it over the other choices. In Desolace.",zone="Desolace",questName="The Corrupter",lore="Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals."},
    [6749]={name="Tiger Band",quality=2,ilvl=31,sourceType="quest_reward",instructions="Reward from the quest 'Willix the Importer' - pick it over the other choices. In Razorfen Kraul.",zone="Razorfen Kraul",questName="Willix the Importer",lore="At last, help has arrived! You have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place."},
    [6751]={name="Mourning Shawl",quality=2,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Mortality Wanes' - pick it over the other choices. In Razorfen Kraul.",zone="Razorfen Kraul",questName="Mortality Wanes",lore="I have not long to live... so... so... weak....the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel... But before I... d-d-die......my wife, Treshala..."},
    [6773]={name="Gelkis Marauder Chain",quality=2,ilvl=42,sourceType="quest_reward",instructions="Reward from the quest 'Khan Hratha' - pick it over the other choices. In Desolace.",zone="Desolace",questName="Khan Hratha",lore="you helped us against the Magram. Now, help us beat the Maraudine! Kill the head of their clan, Khan Hratha! To face him, blow the Maraudine War Horn."},
    [6793]={name="Auric Bracers",quality=2,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'Reagents for Reclaimers Inc.' - pick it over the other choices. In Desolace.",zone="Desolace",questName="Reagents for Reclaimers Inc.",lore="To get paid, you're gonna have to get back to Ironforge and speak to Roetten himself. He'll love getting Leftwitch's package out of the way anyway."},
    [6804]={name="Windstorm Hammer",quality=3,ilvl=34,sourceType="quest_reward",instructions="Reward from the quest 'Final Passage' - pick it over the other choices. In Thousand Needles.",zone="Thousand Needles",questName="Final Passage",lore="You have done well. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles."},
    [6829]={name="Sword of Serenity",quality=3,ilvl=44,sourceType="quest_reward",instructions="Reward from the quest 'In the Name of the Light' - pick it over the other choices. In Scarlet Monastery.",zone="Scarlet Monastery",questName="In the Name of the Light",lore="I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead."},
    [6905]={name="Reef Axe",quality=3,ilvl=27,reqLevel=22,sourceType="boss_drop",instructions="Drops from Gelihast in Blackfathom Deeps.",zone="Blackfathom Deeps",npc="Gelihast"},
    [6906]={name="Algae Fists",quality=3,ilvl=28,reqLevel=23,sourceType="boss_drop",instructions="Drops from Gelihast in Blackfathom Deeps.",zone="Blackfathom Deeps",npc="Gelihast"},
    [7002]={name="Arctic Buckler",quality=3,ilvl=29,sourceType="quest_reward",instructions="Reward from the quest 'Blackfathom Villainy' - pick it over the other choices. In Blackfathom Deeps.",zone="Blackfathom Deeps",questName="Blackfathom Villainy",lore="Strength has left me. Your help is needed! Long ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well."},
