    [12545]={name="Eye of Orgrimmar",quality=3,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'The Princess Saved?' - pick it over the other choices. In Blackrock Depths.",zone="Blackrock Depths",questName="The Princess Saved?",lore="You have slain my husband! My child will be born into this world without a father. I assure you, this child will be the next ruler of the kingdom of Ironforge."},
